@keyframes control-spin { to { transform: rotate(360deg); } }
.action-progress { display: flex; align-items: center; gap: 8px; color: var(--muted); font-size: 13px; line-height: 20px; }
.action-toast { position: fixed; z-index: 40; inset-inline-end: 24px; top: 60px; display: flex; align-items: center; gap: 10px; max-width: calc(100vw - 48px); padding: 12px 14px; border: 1px solid var(--color-border); border-radius: 12.5px; background: var(--app-color-background-elevated-primary); color: var(--color-text-secondary); box-shadow: var(--shadow-lg); font-size: 13px; line-height: 20px; }
